<script setup lang="ts">
import {ref,shallowRef} from 'vue';import {useRouter} from 'vue-router';
import {signInWithEmailAndPassword,getMultiFactorResolver,TotpMultiFactorGenerator,multiFactor,signOut,sendEmailVerification,type MultiFactorResolver,type TotpSecret,type MultiFactorError} from 'firebase/auth';
import BrandMark from '../components/BrandMark.vue';
import QRCode from 'qrcode';import {LockKeyhole,ShieldCheck} from '@lucide/vue';
import {firebaseAuth,emulatorMode,configured,authReady} from '../lib/firebase';import {api} from '../lib/api';
const router=useRouter();const email=ref('');const password=ref('');const code=ref('');const error=ref('');const busy=ref(false);const verificationNeeded=ref(false);const notice=ref('');const resolver=shallowRef<MultiFactorResolver|null>(null);const secret=shallowRef<TotpSecret|null>(null);const qr=ref('');const stage=ref<'password'|'totp'|'enroll'>('password');
async function authorize(){await api('/api/admin/session');await router.push('/admin');}
async function login(){
 if(!firebaseAuth)return;busy.value=true;error.value='';verificationNeeded.value=false;
 try{await authReady;
  if(stage.value==='totp'&&resolver.value){const hint=resolver.value.hints.find(h=>h.factorId===TotpMultiFactorGenerator.FACTOR_ID);if(!hint)throw Error('נדרש אמצעי אימות נתמך.');await resolver.value.resolveSignIn(TotpMultiFactorGenerator.assertionForSignIn(hint.uid,code.value));await authorize();}
  else if(stage.value==='enroll'&&secret.value){await multiFactor(firebaseAuth.currentUser!).enroll(TotpMultiFactorGenerator.assertionForEnrollment(secret.value,code.value),'Authenticator');await signOut(firebaseAuth);stage.value='password';secret.value=null;qr.value='';code.value='';error.value='האימות הנוסף הוגדר. היכנסו שוב עם הסיסמה וקוד מהיישומון.';}
  else{await signInWithEmailAndPassword(firebaseAuth,email.value,password.value);
   if(!emulatorMode&&multiFactor(firebaseAuth.currentUser!).enrolledFactors.length===0){if(!firebaseAuth.currentUser!.emailVerified){verificationNeeded.value=true;throw Error('יש לאמת את כתובת הדוא״ל לפני הגדרת אימות נוסף. לאחר האימות היכנסו שוב.');}const s=await TotpMultiFactorGenerator.generateSecret(await multiFactor(firebaseAuth.currentUser!).getSession());secret.value=s;qr.value=await QRCode.toDataURL(s.generateQrCodeUrl(email.value,'Aviation Consumers Israel'));stage.value='enroll';}
   else await authorize();
  }
 }catch(e){const a=e as MultiFactorError;if(a.code==='auth/multi-factor-auth-required'){resolver.value=getMultiFactorResolver(firebaseAuth,a);stage.value='totp';code.value='';}else error.value=a.code?'הכניסה לא הושלמה. בדקו את הפרטים ואת קוד האימות.':e instanceof Error?e.message:'הכניסה נכשלה.';}finally{busy.value=false;}
}
async function demo(role:'admin'|'reviewer'){email.value=role+'@example.invalid';password.value='DemoOnly!2026';stage.value='password';await login();}
async function verifyEmail(){if(!firebaseAuth?.currentUser)return;busy.value=true;try{await sendEmailVerification(firebaseAuth.currentUser);notice.value='הודעת אימות נשלחה לכתובת החשבון. פתחו את הקישור והיכנסו שוב.';}catch{error.value='לא ניתן לשלוח כעת הודעת אימות. נסו שוב מאוחר יותר.';}finally{busy.value=false;}}
</script>
<template><main id="main-content" class="login-page"><div class="login-card"><RouterLink class="brand" to="/"><BrandMark class="brand-symbol" /><span class="brand-copy"><strong>ארגון צרכני<br/>התעופה בישראל</strong><small>מערכת הצוות</small></span></RouterLink><div class="login-icon"><LockKeyhole :size="28"/></div><h1>כניסה למערכת הניהול</h1><p class="muted">גישה לצוות מורשה בלבד</p><div v-if="!configured" class="alert alert-error">יש להגדיר פרויקט Firebase לפני כניסה.</div><form v-else @submit.prevent="login"><template v-if="stage==='password'"><div class="field"><label for="login-email">דוא״ל</label><input id="login-email" v-model="email" class="input" type="email" autocomplete="username" dir="ltr" required/></div><div class="field"><label for="login-password">סיסמה</label><input id="login-password" v-model="password" class="input" type="password" autocomplete="current-password" dir="ltr" required/></div></template><template v-else><p>{{stage==='enroll'?'סרקו את הקוד ביישומון אימות והזינו את הקוד המתקבל.':'הזינו קוד מהיישומון לאימות דו־שלבי.'}}</p><img v-if="qr" :src="qr" alt="קוד QR להגדרת אימות נוסף" width="220" height="220"/><details v-if="secret"><summary>מפתח להגדרה ידנית</summary><code dir="ltr">{{secret.secretKey}}</code></details><div class="field"><label for="totp">קוד אימות</label><input id="totp" v-model="code" class="input" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" dir="ltr" required/></div></template><p v-if="error" class="alert alert-error" role="alert">{{error}}</p><button class="btn btn-primary" :disabled="busy">{{busy?'מתחברים…':stage==='enroll'?'אישור אמצעי האימות':'כניסה מאובטחת'}}</button></form><div v-if="verificationNeeded" class="demo-login"><button class="btn btn-secondary" :disabled="busy" @click="verifyEmail">שליחת הודעת אימות לדוא״ל</button></div><p v-if="notice" class="alert" role="status">{{notice}}</p><div v-if="emulatorMode" class="demo-login"><p>כניסה לנתונים פיקטיביים בסביבת ההדגמה</p><button class="btn btn-secondary" @click="demo('admin')" :disabled="busy">מנהל הדגמה</button> <button class="btn btn-secondary" @click="demo('reviewer')" :disabled="busy">בודק הדגמה</button><small>אימות TOTP נדרש בענן. ההדגמה משתמשת ב־Auth Emulator.</small></div><p class="login-security"><ShieldCheck :size="16"/> פרטי הכניסה נשמרים בזיכרון הדף בלבד</p></div></main></template>
<style scoped>.login-page{min-height:90vh;background:radial-gradient(at 20% 15%,var(--mint),transparent 55%),var(--pale);display:grid;place-items:center;padding:50px 20px}.login-card{width:min(460px,100%);background:white;border:1px solid var(--line);border-radius:18px;padding:36px;box-shadow:0 20px 70px #102d460a}.login-card .brand-copy strong{font-size:23px}.login-card h1{font-size:28px;margin:17px 0 8px}.login-card>.muted{margin-bottom:26px}.login-icon{display:grid;place-items:center;width:56px;height:56px;border-radius:14px;background:var(--mint);color:var(--blue);margin-top:35px}form>.btn{width:100%;margin-top:18px}.demo-login{margin-top:25px;padding-top:22px;border-top:1px solid var(--line);font-size:14px}.demo-login p{margin-bottom:12px}.demo-login small{display:block;margin-top:12px;color:var(--muted)}.login-security{display:flex;align-items:center;justify-content:center;gap:6px;font-size:12px;color:var(--muted);margin-top:24px}.alert{margin:15px 0}details code{overflow-wrap:anywhere}</style>
